#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    friend void showAccount(const Cat& c);
    friend void rename(Cat& c, string newName);
};

void showAccount(const Cat& c) {
    cout << c.name << " 账上 " << c.fish << " 条喵" << endl;
}

void rename(Cat& c, string newName) {
    c.name = newName;
}

int main() {
    int fish = 0;
    cin >> fish;

    Cat c1("小橘", fish);
    showAccount(c1);
    rename(c1, "大胖");
    showAccount(c1);
    return 0;
}

